import assert from "node:assert/strict";
import { brotliDecompressSync } from "node:zlib";
import { test } from "vitest";
import { canonicalJson, sha256 } from "../src/canonical-json.js";
import { verifySiteGpTableRowReview,
  type SiteGpTableRowReviewVerificationInput } from "../src/site-gp-table-row-review.js";

// Generated by the Python worker from four synthetic PD/GP pages: two clear
// tables and two geometrically ambiguous tables. No project source is included.
const workerFixtureBrotliBase64 = "";
const workerContentHash = "a9670abd90a3296658e558b333907ebb26912728118f757590051e2a361df95f";

function workerJson(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(workerJson).join(",")}]`;
  if (value !== null && typeof value === "object") {
    const item = value as Record<string, unknown>;
    return `{${Object.keys(item).sort()
      .map((key) => `${JSON.stringify(key)}:${workerJson(item[key])}`).join(",")}}`;
  }
  return JSON.stringify(value);
}

function fixture(): SiteGpTableRowReviewVerificationInput {
  const f = JSON.parse(brotliDecompressSync(
    Buffer.from(workerFixtureBrotliBase64, "base64")).toString("utf8")) as any;
  const reviewHash = "d".repeat(64);
  return { objectId: f.objectId, inputManifestHash: f.inputManifestHash,
    sourceFiles: f.sources.map((source: any) => ({
      sourceFileId: source.sourceFileId, objectId: source.objectId,
      sha256: source.sha256, stages: source.stages,
      sourceReviewHash: reviewHash, sectionCode: source.sectionCode })),
    sourceReviews: Object.fromEntries(f.sources.map((source: any) => [source.sourceFileId,
      { sourceSha256: source.sha256, revisionStatus: source.revisionStatus,
        approvalStatus: source.approvalStatus, sectionCode: source.sectionCode,
        pageStages: source.pageStages, contentHash: reviewHash, decisionHash: reviewHash }])),
    textArtifacts: Object.fromEntries(f.textArtifacts.map((artifact: any) => [
      artifact.sourceFileId, { content_json: artifact,
        content_hash: sha256(canonicalJson(artifact)) }])),
    result: f.result };
}

function rehashResult(input: SiteGpTableRowReviewVerificationInput): void {
  const result = input.result as any;
  const { contentHash: _old, ...body } = result;
  result.contentHash = sha256(workerJson(body));
}

function rehashProposal(proposal: any): void {
  const { sourceFileId: _sourceId, sourceSha256: _sourceSha,
    textArtifactSha256: _textSha, pageNumber: _pageNumber,
    sourceRole: _sourceRole, scopedSha256: _scopeSha,
    adjacencyEvidenceSha256: _adjacencySha, ...body } = proposal;
  proposal.adjacencyEvidenceSha256 = sha256(workerJson(body));
  const { scopedSha256: _old, ...scope } = proposal;
  proposal.scopedSha256 = sha256(workerJson(scope));
}

test("accepts independent Python worker fixture with clear and ambiguous table geometry", () => {
  const input = fixture();
  assert.equal((input.result as any).contentHash, workerContentHash);
  assert.equal(verifySiteGpTableRowReview(input), true);
  const rows = (input.result as any).codeRows;
  assert.deepEqual(rows.map((row: any) => [row.proposalCount, row.abstentionCount]),
    [[1, 1], [3, 1]]);
  assert.equal(rows[0].proposals[0].rawQuantity, null);
  assert.equal(rows.every((row: any) => row.status === "ABSTAIN"), true);
});

test("rejects rehashed forged adjacency, locator, quantity, counter and finding", () => {
  const changes: Array<(input: SiteGpTableRowReviewVerificationInput) => void> = [
    (input) => { const p = (input.result as any).codeRows[0].proposals[0];
      p.roles.name.blockText = "Скамья"; rehashProposal(p); },
    (input) => { const p = (input.result as any).codeRows[0].proposals[0];
      p.roles.name.blockIndex = 8; rehashProposal(p); },
    (input) => { const p = (input.result as any).codeRows[1].proposals[1];
      p.roles.thickness.bboxMilliPoints[1] += 1; rehashProposal(p); },
    (input) => { const p = (input.result as any).codeRows[0].proposals[0];
      p.rawQuantity = 2; rehashProposal(p); },
    (input) => { const p = (input.result as any).codeRows[1].proposals[1];
      p.unitInterpretationStatus = "VERIFIED"; rehashProposal(p); },
    (input) => { const row = (input.result as any).codeRows[0];
      row.proposals = []; row.proposalCount = 0;
      row.reasonCodes = [...row.reasonCodes, "NO_UNAMBIGUOUS_ROW_PROPOSAL"].sort(); },
    (input) => { (input.result as any).codeRows[1].abstentionCount = 0; },
    (input) => { (input.result as any).codeRows[1].abstentions[0].anchor.blockIndex = 5; },
    (input) => { (input.result as any).codeRows[0].status = "PASS"; },
    (input) => { (input.result as any).findingCount = 1; },
  ];
  for (const change of changes) {
    const input = fixture();
    change(input);
    rehashResult(input);
    assert.equal(verifySiteGpTableRowReview(input), false);
  }
});

test("rejects stale source review, role, text snapshot and run manifest", () => {
  const changes: Array<(input: SiteGpTableRowReviewVerificationInput) => void> = [
    (input) => { input.sourceReviews["F-FIXTURE"].approvalStatus = "UNAPPROVED"; },
    (input) => { input.sourceReviews["F-FIXTURE"].contentHash = "e".repeat(64); },
    (input) => { input.sourceFiles[0].stages = ["RD"]; },
    (input) => { input.sourceFiles[0].sectionCode = "SPZU"; },
    (input) => { delete input.textArtifacts["F-FIXTURE"]; },
    (input) => { input.textArtifacts["F-FIXTURE"].content_hash = "f".repeat(64); },
    (input) => { input.inputManifestHash = "b".repeat(64); },
  ];
  for (const change of changes) {
    const input = fixture();
    change(input);
    assert.equal(verifySiteGpTableRowReview(input), false);
  }
});
